<?php
require_once __DIR__.'/includes/bootstrap.php';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=val('name',150);$email=strtolower(val('email',190));$pw=$_POST['password']??'';$role=val('role',20);
if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||!is_string($pw)||strlen($pw)<8||!in_array($role,['Student','Company'],true))$err='Enter a name, valid email, password of at least 8 characters, and Student or Company role.';
else try{$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO user_account(email,password_hash,role) VALUES(?,?,?)');$s->execute([$email,password_hash($pw,PASSWORD_DEFAULT),$role]);$uid=(int)$pdo->lastInsertId();if($role==='Student')$pdo->prepare('INSERT INTO student(user_id,name) VALUES(?,?)')->execute([$uid,$name]);else $pdo->prepare('INSERT INTO company(user_id,company_name) VALUES(?,?)')->execute([$uid,$name]);$pdo->commit();header('Location: /skillsync/login.php?registered=1');exit;}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getCode()==='23000'?'Email already registered.':'Registration failed; check schema columns.';}}
page('Register',($err?'<p class="error">'.e($err).'</p>':'').'<form method="post"><input type="hidden" name="csrf_token" value="'.e(csrf_token()).'"><label>Name / company name<input name="name" required></label><label>Email<input type="email" name="email" required></label><label>Password (8+ characters)<input type="password" name="password" minlength="8" required></label><label>Role<select name="role"><option>Student</option><option>Company</option></select></label><button>Register</button></form><p>Admin accounts must be created by the project administrator.</p>');
